// ============================================
// 模拟 FlameMap 输出的火场环境数据
// ============================================
const flameMapData = {
  firePoint: { lat: 45.123, lon: -78.456, confidence: 0.88 },
  weather: { windSpeed: 12.5, windDirection: 135, temp: 28.5, humidity: 35 },
  terrain: { slope: 15.8, aspect: 90 },
  vegetation: { fuelMoisture: 12, fuelLoad: 0.65 },
  riskIndex: 0.72
};

// ============================================
// 模拟可用应急资源
// ============================================
const resourcesData = {
  resources: [
    { id: "R001", type: "waterTanker", location: { lat: 45.110, lon: -78.470 }, status: "available", eta: 25 },
    { id: "R002", type: "groundTeam", location: { lat: 45.090, lon: -78.480 }, status: "available", eta: 40 },
    { id: "R003", type: "drone", location: { lat: 45.130, lon: -78.440 }, status: "available", eta: 15 },
    { id: "R004", type: "bulldozer", location: { lat: 45.140, lon: -78.500 }, status: "available", eta: 60 }
  ]
};

// ============================================
// 合并为统一数据包（供下游使用）
// ============================================
const merged = {
  execution_id: Date.now().toString(),
  timestamp: new Date().toISOString(),
  scene: flameMapData,
  resources: resourcesData.resources,
  data_completeness: 1.0
};

return [{ json: merged }];

// 获取模拟数据中的火点和气象信息
const scene = $input.first().json.scene;
const windSpeed = scene.weather.windSpeed;
const slope = scene.terrain.slope;
const fuelMoisture = scene.vegetation.fuelMoisture;

// ============================================
// 模拟 Rothermel 模型简化计算
// ============================================
const baseSpreadRate = 5.0;  // m/min
const windFactor = Math.min(2.0, windSpeed / 15.0);
const slopeFactor = Math.min(1.5, slope / 30.0);
const moistureFactor = Math.max(0.5, 1.0 - fuelMoisture / 40.0);
const spreadRate = baseSpreadRate * (1 + windFactor) * (1 + slopeFactor) * moistureFactor;

// 模拟火线蔓延方向（8 个主要方向）
const directions = [0, 45, 90, 135, 180, 225, 270, 315];
const spreadVectors = directions.map(dir => ({
  direction: dir,
  speed: spreadRate * (1 + Math.random() * 0.3),
  // 粗略计算下一点坐标（演示用）
  to_lat: scene.firePoint.lat + (dir === 0 ? 0.01 : dir === 180 ? -0.01 : 0),
  to_lon: scene.firePoint.lon + (dir === 90 ? 0.01 : dir === 270 ? -0.01 : 0)
}));

// 模拟风险网格（受威胁目标）
const threatenedTargets = [];
if (Math.random() > 0.5) threatenedTargets.push("village_A");
if (Math.random() > 0.7) threatenedTargets.push("power_line_01");

return [{
  json: {
    spread_vectors: spreadVectors,
    risk_grid: {
      cells: [],
      threatened_targets: threatenedTargets
    },
    spread_rate_max: spreadRate,
    confidence: 0.85
  }
}];

// ============================================
// 多因子耦合风险场构建（适配 Merge 或双输入）
// ============================================

// 获取所有输入项（两个并行分支的输出）
const items = $input.all();

if (items.length < 2) {
  throw new Error(`预期收到2个并行分支的输出，实际只收到 ${items.length} 个。请检查两个分支是否都正确连接到本节点。`);
}

let envResult = null;
let spreadResult = null;

// 遍历输入项，根据特征字段区分
for (const item of items) {
  const data = item.json;
  // 环境评估结果的特征：包含 situation_id
  if (data.situation_id) {
    envResult = data;
  }
  // 火势推演结果的特征：包含 spread_vectors
  else if (data.spread_vectors) {
    spreadResult = data;
  }
}

if (!envResult) {
  throw new Error('未找到环境评估智能体的输出（缺少 situation_id 字段）');
}
if (!spreadResult) {
  throw new Error('未找到火势推演智能体的输出（缺少 spread_vectors 字段）');
}

// 获取原始场景数据（从 DataGenerator 节点获取）
const dataGenNode = $('DataGenerator');
if (!dataGenNode) {
  throw new Error('未找到 DataGenerator 节点');
}
const scene = dataGenNode.first().json.scene;
const resources = dataGenNode.first().json.resources;

// ============================================
// 多因子耦合计算
// ============================================
const windSpeed = scene.weather.windSpeed;
const slope = scene.terrain.slope;
const fuelMoisture = scene.vegetation.fuelMoisture;

// 各因子归一化
const windFactor = Math.min(1.0, windSpeed / 20.0);
const slopeFactor = Math.min(1.0, slope / 35.0);
const moistureFactor = Math.max(0, 1.0 - fuelMoisture / 30.0);
const spreadRate = spreadResult.spread_rate_max || 5.0;
const intensityFactor = Math.min(1.0, spreadRate / 20.0);
const passageRisk = (slopeFactor * 0.6 + moistureFactor * 0.4);

// 权重（α, β, γ, δ, ε）
const weights = {
  wind: 0.30,
  slope: 0.25,
  moisture: 0.20,
  passage: 0.10,
  intensity: 0.15
};

const totalRisk = 
  weights.wind * windFactor +
  weights.slope * slopeFactor +
  weights.moisture * moistureFactor +
  weights.passage * passageRisk +
  weights.intensity * intensityFactor;

let riskLevel;
if (totalRisk >= 0.7) riskLevel = 'extreme';
else if (totalRisk >= 0.5) riskLevel = 'high';
else if (totalRisk >= 0.3) riskLevel = 'moderate';
else riskLevel = 'low';

const riskPackage = {
  package_type: 'risk_package',
  version: '1.0',
  timestamp: new Date().toISOString(),
  risk_score: totalRisk,
  risk_level: riskLevel,
  risk_breakdown: {
    wind_factor: windFactor,
    slope_factor: slopeFactor,
    moisture_factor: moistureFactor,
    passage_risk: passageRisk,
    intensity_factor: intensityFactor,
    weights: weights
  },
  predicted_affected_zones: (spreadResult.risk_grid && spreadResult.risk_grid.threatened_targets) || [],
  recommended_priority: riskLevel === 'extreme' ? 'immediate_response' :
                        (riskLevel === 'high' ? 'high_priority' : 'routine')
};

const aggregatedPackage = {
  package_type: 'aggregated_situation_risk',
  version: '1.0',
  situation: envResult,
  risk: riskPackage,
  spread_prediction: spreadResult,
  resources: resources
};

return [{ json: aggregatedPackage }];

