      "strategy": "建立隔离带，配合地面队伍推进",
      "required_resources": ["R002", "R004"],
      "estimated_control_time": 120,
      "safety_checks": {"wind_ok": true, "slope_ok": true, "evacuation_ready": true}
    },
    {
      "plan_id": "plan_C",
      "plan_type": "conservative",
      "strategy": "优先疏散周边居民，设置缓冲区",
      "required_resources": ["R002"],
      "estimated_control_time": 180,
      "safety_checks": {"wind_ok": true, "slope_ok": true, "evacuation_ready": true}
