const plan = plans.find(p => p.plan_id === 'plan_A');
if (!plan) throw new Error('未找到 plan_A');

// 从 DataGenerator 获取火点和资源
const dataGen = $('DataGenerator');
const scene = dataGen.first().json.scene;
const firePoint = scene.firePoint;   // 注意大小写
const resources = dataGen.first().json.resources;

if (!firePoint || typeof firePoint.lon === 'undefined') {
  throw new Error('firePoint 无效，请检查 DataGenerator 输出中的 scene.firePoint');
}

const matchedResources = resources.filter(r => plan.required_resources.includes(r.id));

function calculateRoute(from, to) {
  if (!from || !to) throw new Error('起点或终点无效');
  const dx = to.lon - from.lon;
  const dy = to.lat - from.lat;
  const distanceKm = Math.hypot(dx, dy) * 111;
  const estimatedMinutes = distanceKm * 2;
  return {
    waypoints: [from, to],
    distance_km: distanceKm,
    estimated_time_min: Math.round(estimatedMinutes)
  };
}

const taskPackage = {
  package_type: 'task_package',
  plan_id: plan.plan_id,
  plan_type: plan.plan_type,
  timestamp: new Date().toISOString(),
  tasks: matchedResources.map(r => {
    if (!r.location) throw new Error(`资源 ${r.id} 缺少 location`);
    return {
      resource_id: r.id,
      task_type: 'direct_suppression',
      target: firePoint,
      main_route: calculateRoute(r.location, firePoint),
      backup_route: calculateRoute(r.location, firePoint),
      evacuation_route: { type: 'evacuation', exit_points: [] },
      estimated_eta_min: r.eta,
      priority: 'critical'
    };
  }),
  safety_checks: plan.safety_checks,
  execution_instructions: plan.strategy,
  status: 'dispatched'
};

return [{ json: taskPackage }];

