const taskPayload = $input.first().json;
console.log('原始任务包:', JSON.stringify(taskPayload, null, 2));

// 获取 execution_id
const dataGen = $('DataGenerator');  // 确保节点名称正确，如“模拟数据生成器”
let execution_id = 'unknown';
if (dataGen && dataGen.first()) {
